import{_ as t,o as a,c as n,a3 as o}from"./chunks/framework.CchDE9cb.js";const s="/capacitylens/assets/settings-top.Ny5TimQS.jpg",i="/capacitylens/assets/settings-toggles.DIvNDGy4.jpg",y=JSON.parse(`{"title":"Settings","description":"The company-wide switches that control what's visible on the schedule, plus the ones that are just yours.","frontmatter":{"title":"Settings","description":"The company-wide switches that control what's visible on the schedule, plus the ones that are just yours."},"headers":[],"relativePath":"guide/settings.md","filePath":"guide/settings.md","lastUpdated":null}`),r={name:"guide/settings.md"};function l(d,e,h,c,p,g){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>Settings is one scrollable page of plain-language switches — no tabs, no separate admin console. Most settings apply to the whole company; a few apply only to your own device. This page covers the two switches worth understanding early, plus a map of everything else.</p><p><img src="'+s+'" alt="Settings page showing Company name, Scheduling mode (Hours/Days/Blocks) and the frozen Calendar card"></p><h2 id="internal-work-visibility" tabindex="-1">Internal work visibility <a class="header-anchor" href="#internal-work-visibility" aria-label="Permalink to &quot;Internal work visibility&quot;">​</a></h2><p>Two switches under <strong>Internal work</strong>, both on by default, control whether internal and non-billable work shows up on the schedule at all:</p><ul><li><strong>Show internal projects</strong></li><li><strong>Show internal activities</strong></li></ul><p>Turning either off hides the matching bars from the schedule — useful if some of your team only wants to see client work. It doesn&#39;t change capacity: hidden internal work still counts toward a person&#39;s <a href="/capacitylens/reference/glossary">utilisation</a>, so someone who&#39;s fully booked with internal work still shows as fully booked. Nothing is deleted, and the bars come back the moment you turn the switch back on.</p><h2 id="inline-activity-creation" tabindex="-1">Inline activity creation <a class="header-anchor" href="#inline-activity-creation" aria-label="Permalink to &quot;Inline activity creation&quot;">​</a></h2><p>When you&#39;re booking an allocation and the <a href="/capacitylens/reference/glossary">activity</a> you need doesn&#39;t exist yet, the allocation form normally lets you add it on the spot without leaving the form. That convenience is controlled by <strong>Inline activity creation</strong> under <strong>Activity creation</strong>, on by default. Turning it off means everyone has to create new activities from the <strong>Activities</strong> page first, then pick from the existing list when they allocate — useful if you&#39;d rather keep activity names tidy and reviewed.</p><p><img src="'+i+'" alt="Settings page showing Placeholders and External toggles off by default, Internal work toggles on, each with a plain-language explanation"></p><h2 id="everything-else-on-the-page" tabindex="-1">Everything else on the page <a class="header-anchor" href="#everything-else-on-the-page" aria-label="Permalink to &quot;Everything else on the page&quot;">​</a></h2><p>The rest of Settings, roughly top to bottom:</p><table tabindex="0"><thead><tr><th>Section</th><th>What it controls</th></tr></thead><tbody><tr><td>Company</td><td>The company&#39;s display name.</td></tr><tr><td>Scheduling</td><td>Whether allocations are entered as Hours, Days or Blocks — see <a href="/capacitylens/guide/projects-and-allocations">Projects and allocations</a>.</td></tr><tr><td>Calendar</td><td>Week start, timezone and language. Set once when the company is created and frozen after, so &quot;today&quot; means the same thing for everyone.</td></tr><tr><td>Disciplines</td><td>Whether people are grouped by <a href="/capacitylens/reference/glossary">discipline</a> (Design, Development, and so on) across the app. On by default. Disciplines themselves — their names and colours — are created on the standalone <strong>Disciplines</strong> page in the main navigation, not here; see <a href="/capacitylens/guide/people-and-placeholders">People and placeholders</a>.</td></tr><tr><td>Schedule (this device)</td><td>Minimise weekends, snap to week start, and compact view — your own display preferences, not shared with teammates.</td></tr><tr><td>Internal work colours</td><td>Whether internal work uses grey bars (default) or the same colour palette as everything else.</td></tr><tr><td>Placeholders</td><td>Whether unfilled <a href="/capacitylens/reference/glossary">placeholder</a> slots are available. Off by default. See <a href="/capacitylens/guide/people-and-placeholders">People and placeholders</a>.</td></tr><tr><td>External</td><td>Whether <a href="/capacitylens/reference/glossary">external parties</a> — outside companies you hand work to but don&#39;t manage, like print shops — are available. Off by default. See <a href="/capacitylens/guide/people-and-placeholders">People and placeholders</a>.</td></tr><tr><td>Allocation bars (this device)</td><td>Whether bars show the client name and project name ahead of the activity name.</td></tr><tr><td>Utilisation</td><td>Which utilisation figures appear on the schedule: total, per-discipline and personal.</td></tr><tr><td>Appearance (this device)</td><td>Light, dark, or match your system theme.</td></tr><tr><td>Offline access</td><td>Keep the last company you opened available on this device for seven days, read only. See <a href="/capacitylens/guide/offline-access">Offline access</a>.</td></tr><tr><td>Device data</td><td>Clear everything CapacityLens has stored on this device.</td></tr><tr><td>Account</td><td>Your sign-in email and a sign-out button.</td></tr><tr><td>Security</td><td>Change your password and review your active sign-in sessions, in password mode.</td></tr><tr><td>Archived &amp; deleted</td><td>Restore something you archived, or permanently delete it. See <a href="/capacitylens/guide/people-and-placeholders">People and placeholders</a>.</td></tr></tbody></table><p>Every switch on this page comes with its own plain-language explanation of what it changes and what happens to your data if you turn it back off — nothing here deletes data, it just changes what&#39;s shown.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Sections marked &quot;this device&quot; only affect your own browser. Everything else is shared by the whole company and needs Editor access or above to change.</p></div><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><p><a href="/capacitylens/guide/people-and-placeholders">People and placeholders</a> and <a href="/capacitylens/guide/projects-and-allocations">Projects and allocations</a> cover the two switches above in more detail.</p>',17)])])}const f=t(r,[["render",l]]);export{y as __pageData,f as default};
